-- Lösungswege für die Forderungskarte (ohne Punkte). Upsert, damit gespeicherte Forderungen ihren Verweis behalten.
insert into public.instrumente (id, thema_id, name, begruendung, evidenz, beleg_studie_url, ebene, entspricht, ki_entwurf, entwurf_herkunft, nebenwirkungen) values
  (10443, 34, 'Polizeiliche Kontrollbefugnisse, Kontrollorte und Kontrolldichte ausweiten (Land)', 'Mehr Kontrollen und Befugnisse erhöhen die Zahl der Kontakte, die als belastend gelten; Studien finden nur schwache, uneinheitliche Effekte auf Kriminalität. Für das Ziel respektvoller, seltener Kontrollen spricht nichts.', 'gemischt', 'https://fullfact.org/crime/does-stop-search-work/', 'land', null, true, 'blind', null),
  (10444, 34, 'Polizeiliche Kontrollbefugnisse und Kontrollen ausweiten (Bund)', 'Erweiterte Befugnisse und mehr Kontrollen erhöhen die Zahl der Kontakte; für eine respektvollere oder nachvollziehbarere Behandlung bei Kontrollen bietet das keinen Ansatz.', 'gemischt', 'https://fullfact.org/crime/does-stop-search-work/', 'bund', null, true, 'blind', null),
  (10445, 34, 'Anlasslose Kontrollen abschaffen oder eng begrenzen (Land)', 'Weniger anlasslose Kontrollen senken die Zahl belastender Kontakte; ihr Nutzen gegen Kriminalität gilt als schwach. Dagegen: Wirkung der Abschaffung in Deutschland kaum untersucht, Polizei verliert ein Werkzeug.', 'gemischt', 'https://fullfact.org/crime/does-stop-search-work/', 'land', null, true, 'blind', null),
  (10446, 34, 'Kontrollorte und Verbotszonen überprüfen, Kriterien präzisieren und befristen (Land)', 'Klarere Kriterien und Überprüfung können anlasslose Kontrollen begrenzen und nachvollziehbarer machen; ob die Zahl der Kontrollen spürbar sinkt, bleibt offen.', 'offen', null, 'land', null, true, 'blind', null),
  (10447, 34, 'Kontrollquittung mit Grund und Rechtsgrundlage bei Polizeikontrollen (Land)', 'Erfahrungen aus Spanien (Fuenlabrada) zeigen mehr Transparenz, weniger Spannung und selektivere Kontrollen. Dagegen: kaum kontrollierte Studien, zusätzlicher Aufwand für die Polizei.', 'gemischt', 'https://www.justiceinitiative.org/voices/q-and-a-how-a-system-to-document-police-stops-improved-policing-in-fuenlabrada-spain', 'land', null, true, 'blind', null),
  (10448, 34, 'Aus- und Fortbildung zu Kommunikation, Deeskalation, Grundrechten und Antidiskriminierung (Land)', 'Ein randomisiertes US-Experiment zeigt: Training in fairem Verfahren senkt wahrgenommene Schikane und Gewalt. Dagegen: Inhalte hier meist unbestimmt, Effekte schwinden ohne Begleitung durch Vorgesetzte.', 'belegt', 'https://cebcp.org/weisburd-procedural-justice-hot-spots/', 'land', null, true, 'blind', null),
  (10449, 34, 'Deeskalation als verbindliche Einsatzstrategie (Land)', 'Deeskalationsansätze senkten in einem US-Feldversuch Gewaltanwendung und Verletzungen deutlich. Dagegen: Belege stammen aus wenigen Programmen, Strategie ohne Training bleibt unbestimmt.', 'belegt', 'https://nij.ojp.gov/topics/articles/what-works-de-escalation-training', 'land', null, true, 'blind', null),
  (10450, 34, 'Aus- und Fortbildung der Polizei allgemein ausbauen und modernisieren (Land)', 'Mehr oder modernere Ausbildung kann das Verhalten bei Kontakten verbessern, die Maßnahmen nennen aber keine Inhalte zu Kommunikation oder Umgang mit Betroffenen.', 'offen', null, 'land', null, true, 'blind', null),
  (10451, 34, 'Bürgernahe Polizei mit Kontaktbereichsbeamten und Fußstreifen ausbauen (Land)', 'Eine Meta-Analyse findet positive Effekte bürgernaher Polizeiarbeit auf Zufriedenheit und Legitimität, kaum auf Kriminalität. Dagegen: Gesamtbefund uneindeutig, braucht zusätzliches Personal.', 'belegt', 'https://cris.huji.ac.il/en/publications/community-oriented-policing-to-reduce-crime-disorder-and-fear-and/', 'land', null, true, 'blind', null),
  (10452, 34, 'Supervision und psychologische Begleitung für Polizeikräfte ausbauen (Land)', 'Reflexion von Einsätzen kann Einsatzpraxis verbessern; ein Effekt auf den Umgang mit Betroffenen ist kaum untersucht.', 'offen', null, 'land', null, true, 'blind', null),
  (10453, 34, 'Polizei diverser aufstellen und interkulturell öffnen (Land)', 'Vielfältigeres Personal kann Kommunikation erleichtern; ob es das Verhalten bei Kontakten spürbar ändert, ist wenig belegt.', 'offen', null, 'land', null, true, 'blind', null),
  (10454, 34, 'Bodycam-Pflicht bei Zwang oder auf Verlangen mit Einsichtsrecht für Betroffene (Land)', 'Bodycams senken laut Campbell-Review Beschwerden, Effekt auf Gewalt unklar; feste Einschaltregeln scheinen zu helfen. Aufnahmen erleichtern die Klärung von Vorwürfen.', 'gemischt', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC8356344/', 'land', null, true, 'blind', null),
  (10455, 34, 'Individuelle oder pseudonyme Kennzeichnungspflicht für Polizeikräfte (Land)', 'Kennzeichnung erleichtert die Identifizierung bei Vorwürfen, gerichtlich gebilligt. Dagegen: Wirkung auf Einstellungsquoten kaum untersucht, Identifizierung scheitert nur in einem Teil der Fälle.', 'offen', null, 'land', null, true, 'blind', null),
  (10456, 34, 'Individuelle oder anonymisierte Kennzeichnungspflicht für Polizeikräfte des Bundes (Bund)', 'Kennzeichnung erleichtert die Identifizierung bei Vorwürfen gegen Bundespolizisten. Dagegen: Wirkung auf die Aufklärung kaum untersucht.', 'offen', null, 'bund', null, true, 'blind', null),
  (10457, 34, 'Unabhängige Polizeibeschwerdestelle mit eigenen Untersuchungsbefugnissen (Land)', 'Studien finden bei unabhängigen Stellen mit Befugnissen häufiger bestätigte Vorwürfe; die Designs sind aber schwach, andere Befunde gegenläufig.', 'gemischt', 'https://policing.counciloncj.org/assessing-the-evidence/xi-civilian-oversight', 'land', null, true, 'blind', null),
  (10458, 34, 'Polizeibeauftragte oder Ombudsstelle einrichten oder stärken, ohne konkrete Ermittlungsbefugnisse (Land)', 'Eine Anlaufstelle erleichtert Beschwerden; Befunde deuten aber darauf hin, dass Stellen ohne echte Befugnisse wenig an der Aufklärung ändern.', 'gemischt', 'https://policing.counciloncj.org/assessing-the-evidence/xi-civilian-oversight', 'land', null, true, 'blind', null),
  (10459, 34, 'Polizeibeauftragte abschaffen (Land)', 'Entfernt eine unabhängige Beschwerdemöglichkeit; zur Klärung von Fehlern bleiben nur die Wege, deren hohe Einstellungsquote die Ursache ist.', 'gemischt', 'https://policing.counciloncj.org/assessing-the-evidence/xi-civilian-oversight', 'land', null, true, 'blind', null),
  (10460, 34, 'Polizeibeauftragte abschaffen (Bund)', 'Entfernt eine unabhängige Beschwerdemöglichkeit beim Bund; Vorwürfe blieben allein bei Staatsanwaltschaften, deren häufige Einstellungen die Ursache sind.', 'gemischt', 'https://policing.counciloncj.org/assessing-the-evidence/xi-civilian-oversight', 'bund', null, true, 'blind', null),
  (10461, 34, 'Dokumentationspflichten der Polizei zurücknehmen oder reduzieren (Land)', 'Weniger Dokumentation entlastet die Polizei, erschwert aber die Nachprüfung von Einsätzen und die Klärung von Vorwürfen.', 'offen', null, 'land', null, true, 'blind', null),
  (10462, 34, 'Disziplinarverfahren bei Fehlverhalten beschleunigen und konsequent führen (Land)', 'Schnellere, konsequente Disziplinarverfahren können Fehlverhalten ahnden; sie bleiben aber polizeiintern, die Wirkung auf die Klärung von Vorwürfen ist kaum untersucht.', 'offen', null, 'land', null, true, 'blind', null)
