insert into public.massnahmen (id, thema_id, partei_id, land, beschreibung, ursachen_ids, instrument_id, wirksamkeit, umsetzbarkeit,
  rollen_modifikator, begruendung, beleg_programm_url, beleg_studie_url, evidenz, stand, geprueft, ki_entwurf, entwurf_herkunft, nebenwirkungen) values
  (10463, 34, 11, null, 'Keine Pflicht der Bundespolizei, nach einer Kontrolle eine Kontrollquittung auszustellen.', '{3401}', null, 0, 3, null, 'Verzicht auf Kontrollquittungen lässt Kontrollen der Bundespolizei für Betroffene so wenig nachvollziehbar wie bisher.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=40', null, 'offen', '2026-10-21', false, true, 'blind', null),
  (10464, 34, 11, null, 'Sonderermittler wie den Polizeibeauftragten des Bundes abschaffen; Vorwürfe durch Staatsanwaltschaften und Gerichte klären lassen.', '{3403}', 10460, 0, 3, null, 'Entfernt eine unabhängige Beschwerdemöglichkeit beim Bund; Vorwürfe blieben allein bei Staatsanwaltschaften, deren häufige Einstellungen die Ursache sind.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=40', 'https://policing.counciloncj.org/assessing-the-evidence/xi-civilian-oversight', 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10465, 34, 11, null, 'Keine Kennzeichnungspflicht für Bundespolizisten.', '{3403}', null, 0, 3, null, 'Verzicht auf Kennzeichnung lässt die Identifizierung bei Vorwürfen gegen Bundespolizisten unverändert schwierig.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=40', null, 'offen', '2026-10-21', false, true, 'blind', null),
  (10466, 34, 11, null, 'Bodycams bei Polizeieinsätzen, auch in Wohnräumen.', '{3403}', null, 1, 2, null, 'Bodycams können Beschwerden senken und Beweise sichern, Effekt auf Gewalt unklar; ohne Einschaltpflicht und Einsicht für Betroffene begrenzt, Einsatz in Wohnungen rechtlich heikel.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=40', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC8356344/', 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10467, 34, 11, 'BE', 'Kriminalitätsauffällige Räume können kurzfristig als kriminalbelastete Orte erklärt werden', '{3401}', 10443, 0, 3, null, 'Mehr Kontrollen und Befugnisse erhöhen die Zahl der Kontakte, die als belastend gelten; Studien finden nur schwache, uneinheitliche Effekte auf Kriminalität. Für das Ziel respektvoller, seltener Kontrollen spricht nichts.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=8', 'https://fullfact.org/crime/does-stop-search-work/', 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10468, 34, 11, 'BE', 'Polizeikräfte regelmäßig aus- und fortbilden; operative Dienstbereiche mit Tasern ausstatten', '{3402}', 10450, 1, 3, null, 'Mehr oder modernere Ausbildung kann das Verhalten bei Kontakten verbessern, die Maßnahmen nennen aber keine Inhalte zu Kommunikation oder Umgang mit Betroffenen.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=8', null, 'offen', '2026-10-21', false, true, 'blind', null),
  (10469, 34, 11, 'BE', 'Schießtrainings der Polizei verdoppeln', '{3402}', null, 0, 3, null, 'Mehr Schießtraining betrifft Waffenhandhabung, nicht Kommunikation oder respektvollen Umgang bei Kontakten.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=7', null, 'offen', '2026-10-21', false, true, 'blind', null),
  (10470, 34, 11, 'BE', 'Doppelstrukturen abbauen, darunter die Stelle des Polizeibeauftragten', '{3403}', 10459, 0, 3, null, 'Entfernt eine unabhängige Beschwerdemöglichkeit; zur Klärung von Fehlern bleiben nur die Wege, deren hohe Einstellungsquote die Ursache ist.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=118', 'https://policing.counciloncj.org/assessing-the-evidence/xi-civilian-oversight', 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10471, 34, 11, 'BE', 'Berichts- und Dokumentationspflichten der Polizei stark zurückfahren', '{3403}', 10461, 0, 3, null, 'Weniger Dokumentation entlastet die Polizei, erschwert aber die Nachprüfung von Einsätzen und die Klärung von Vorwürfen.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=8', null, 'offen', '2026-10-21', false, true, 'blind', null),
  (10472, 34, 11, 'MV', 'Mehr Polizei an Innenstädten und Kriminalitätsschwerpunkten, höherer Kontrolldruck und wirksamere Platzverweise im öffentlichen Raum', '{3401}', 10443, 0, 3, null, 'Mehr Kontrollen und Befugnisse erhöhen die Zahl der Kontakte, die als belastend gelten; Studien finden nur schwache, uneinheitliche Effekte auf Kriminalität. Für das Ziel respektvoller, seltener Kontrollen spricht nichts.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=31', 'https://fullfact.org/crime/does-stop-search-work/', 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10473, 34, 11, 'MV', 'Ausbildung der Polizei analysieren, Ausbildungsinhalte modernisieren und digital aufbereiten', '{3402}', 10450, 1, 3, null, 'Mehr oder modernere Ausbildung kann das Verhalten bei Kontakten verbessern, die Maßnahmen nennen aber keine Inhalte zu Kommunikation oder Umgang mit Betroffenen.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=28', null, 'offen', '2026-10-21', false, true, 'blind', null),
  (10474, 34, 11, 'ST', 'Befugnisse und Kompetenzen der Polizei erweitern', '{3401}', 10443, 0, 3, null, 'Mehr Kontrollen und Befugnisse erhöhen die Zahl der Kontakte, die als belastend gelten; Studien finden nur schwache, uneinheitliche Effekte auf Kriminalität. Für das Ziel respektvoller, seltener Kontrollen spricht nichts.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=6', 'https://fullfact.org/crime/does-stop-search-work/', 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10475, 34, 11, 'ST', 'Bodycam-Einsatz auch in Wohnungen ermöglichen, um deeskalierend zu wirken und Dokumentation zu sichern', '{3403}', null, 1, 2, null, 'Bodycams in Wohnungen sichern Beweise, Wirkung auf Gewalt laut Review unklar; ohne Rechte für Betroffene dienen sie vor allem der Polizei, Art. 13 GG setzt Grenzen.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=7', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC8356344/', 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10476, 34, 12, null, 'Modernes Bundespolizeigesetz mit klaren Befugnissen der Bundespolizei', '{3401}', 10444, 0, 3, null, 'Erweiterte Befugnisse und mehr Kontrollen erhöhen die Zahl der Kontakte; für eine respektvollere oder nachvollziehbarere Behandlung bei Kontrollen bietet das keinen Ansatz.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=43', 'https://fullfact.org/crime/does-stop-search-work/', 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10477, 34, 12, 'BE', 'Verdachtsunabhängige Kontrollen räumlich und zeitlich auf das notwendige Minimum begrenzen; Waffen- und Messerverbotszonen als Ausnahme', '{3401}', 10445, 2, 3, null, 'Weniger anlasslose Kontrollen senken die Zahl belastender Kontakte; ihr Nutzen gegen Kriminalität gilt als schwach. Dagegen: Wirkung der Abschaffung in Deutschland kaum untersucht, Polizei verliert ein Werkzeug.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=30', 'https://fullfact.org/crime/does-stop-search-work/', 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10478, 34, 12, 'BE', 'Interkulturelle Kompetenz der Polizei ausbauen und Sensibilisierung in Aus- und Fortbildung stärken', '{3402}', 10448, 2, 3, null, 'Ein randomisiertes US-Experiment zeigt: Training in fairem Verfahren senkt wahrgenommene Schikane und Gewalt. Dagegen: Inhalte hier meist unbestimmt, Effekte schwinden ohne Begleitung durch Vorgesetzte.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=31', 'https://cebcp.org/weisburd-procedural-justice-hot-spots/', 'belegt', '2026-10-21', false, true, 'blind', null),
  (10479, 34, 12, 'BE', 'Digitales Community Policing starten, das besonders junge Menschen online erreicht', '{3402}', null, 1, 3, null, 'Online-Ansprache junger Menschen kann Vertrauen und Kommunikation fördern; Wirkung digitaler Bürgerpolizei auf Kontakte kaum untersucht.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=31', null, 'offen', '2026-10-21', false, true, 'blind', null),
  (10480, 34, 12, 'BE', 'Routinemäßige Supervision für Polizeibeschäftigte, um Einsatzgeschehen zu reflektieren, ausbauen', '{3402}', 10452, 1, 3, null, 'Reflexion von Einsätzen kann Einsatzpraxis verbessern; ein Effekt auf den Umgang mit Betroffenen ist kaum untersucht.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=31', null, 'offen', '2026-10-21', false, true, 'blind', null),
  (10481, 34, 12, 'BE', 'Ombudsstelle des Landesantidiskriminierungsgesetzes mit Initiativ- und Befragungsrechten und Berichtspflicht ausstatten', '{3403}', 10458, 1, 3, null, 'Eine Anlaufstelle erleichtert Beschwerden; Befunde deuten aber darauf hin, dass Stellen ohne echte Befugnisse wenig an der Aufklärung ändern.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=48', 'https://policing.counciloncj.org/assessing-the-evidence/xi-civilian-oversight', 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10482, 34, 12, 'BE', 'Einheit für interne Ermittlungen bei strafrechtlichen Vorwürfen gegen Beschäftigte des öffentlichen Dienstes anstreben', '{3403}', null, 1, 3, null, 'Eine Ermittlungseinheit außerhalb der Polizei, aber im Innenressort, kann Vorwürfe distanzierter prüfen; volle Unabhängigkeit fehlt, Wirkung offen.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=31', null, 'offen', '2026-10-21', false, true, 'blind', null),
  (10483, 34, 12, 'MV', 'Angeleitete Reflexion, Feedbackangebote und Begleitung für Polizeibeschäftigte in belastenden Situationen ausbauen', '{3402}', 10452, 1, 3, null, 'Reflexion von Einsätzen kann Einsatzpraxis verbessern; ein Effekt auf den Umgang mit Betroffenen ist kaum untersucht.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=48', null, 'offen', '2026-10-21', false, true, 'blind', null),
