  (10485, 34, 12, 'ST', 'Aus- und Fortbildung der Polizei modernisieren und an neue Einsatzlagen anpassen', '{3402}', 10450, 1, 3, null, 'Mehr oder modernere Ausbildung kann das Verhalten bei Kontakten verbessern, die Maßnahmen nennen aber keine Inhalte zu Kommunikation oder Umgang mit Betroffenen.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=29', null, 'offen', '2026-10-21', false, true, 'blind', null),
  (10486, 34, 12, 'ST', 'Unabhängigkeit des Polizeibeauftragten stärken', '{3403}', 10458, 1, 3, null, 'Eine Anlaufstelle erleichtert Beschwerden; Befunde deuten aber darauf hin, dass Stellen ohne echte Befugnisse wenig an der Aufklärung ändern.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=29', 'https://policing.counciloncj.org/assessing-the-evidence/xi-civilian-oversight', 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10487, 34, 13, null, 'Ticketsystem für Polizeikontrollen, das die Gründe nennt, für mehr Transparenz', '{3401}', null, 2, 3, null, 'Kontrollbelege mit Grund machen Kontrollen nachvollziehbar; Erfahrungen aus Spanien sind positiv, kontrollierte Studien fehlen. Gilt nur für die Bundespolizei.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=134', 'https://www.justiceinitiative.org/voices/q-and-a-how-a-system-to-document-police-stops-improved-policing-in-fuenlabrada-spain', 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10488, 34, 13, null, 'Polizeiliche Kontrollbefugnisse so ausgestalten, dass sie rechtssicher angewandt werden können', '{3401}', null, 1, 3, null, 'Rechtssichere Kontrollbefugnisse können Kontrollen nachvollziehbarer machen; ob sie seltener oder verhältnismäßiger werden, bleibt offen.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=134', null, 'offen', '2026-10-21', false, true, 'blind', null),
  (10489, 34, 13, null, 'Aus- und Fortbildung der Polizei zu Diversität und Fehlerkultur', '{3402}', null, 2, 3, null, 'Fortbildung zu Diversität und Fehlerkultur kann den Umgang bei Kontakten verbessern (US-Experiment zu fairem Verfahren); wirkt nur bei der Bundespolizei, Inhalte unbestimmt.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=134', 'https://cebcp.org/weisburd-procedural-justice-hot-spots/', 'belegt', '2026-10-21', false, true, 'blind', null),
  (10490, 34, 13, null, 'Umgang mit psychischen Ausnahmesituationen stärker in den Fokus nehmen und die psychosoziale Notfallversorgung verbessern', '{3402}', null, 1, 2, null, 'Stärkerer Fokus auf psychische Ausnahmesituationen kann die Einsatzpraxis verbessern, bleibt aber unbestimmt; Polizeipraxis liegt überwiegend bei den Ländern.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=134', null, 'offen', '2026-10-21', false, true, 'blind', null),
  (10491, 34, 13, null, 'Polizeibeauftragten des Bundes als Anlaufstelle stärken und weiterentwickeln', '{3403}', null, 1, 3, null, 'Stärkung des Polizeibeauftragten des Bundes erleichtert Beschwerden; ohne konkrete Befugnisse bleibt die Wirkung auf die Aufklärung laut Forschung begrenzt.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=134', 'https://policing.counciloncj.org/assessing-the-evidence/xi-civilian-oversight', 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10492, 34, 13, null, 'Anonymisierte Kennzeichnungspflicht für die Bundespolizei', '{3403}', 10456, 2, 3, null, 'Kennzeichnung erleichtert die Identifizierung bei Vorwürfen gegen Bundespolizisten. Dagegen: Wirkung auf die Aufklärung kaum untersucht.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=134', null, 'offen', '2026-10-21', false, true, 'blind', null),
  (10493, 34, 13, 'BE', 'Digitale Kontrollquittung, die jede Person über den Anlass einer Polizeikontrolle informiert.', '{3401}', 10447, 2, 3, null, 'Erfahrungen aus Spanien (Fuenlabrada) zeigen mehr Transparenz, weniger Spannung und selektivere Kontrollen. Dagegen: kaum kontrollierte Studien, zusätzlicher Aufwand für die Polizei.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=228', 'https://www.justiceinitiative.org/voices/q-and-a-how-a-system-to-document-police-stops-improved-policing-in-fuenlabrada-spain', 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10494, 34, 13, 'BE', 'Kriminalitätsbelastete Orte und Messer- und Waffenverbotszonen überprüfen und, wo nötig, abschaffen.', '{3401}', 10446, 1, 3, null, 'Klarere Kriterien und Überprüfung können anlasslose Kontrollen begrenzen und nachvollziehbarer machen; ob die Zahl der Kontrollen spürbar sinkt, bleibt offen.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=228', null, 'offen', '2026-10-21', false, true, 'blind', null),
  (10495, 34, 13, 'BE', 'Demokratiebildung, Diskriminierungskritik und Kommunikation in Aus- und Fortbildung der Sicherheitsbehörden fördern.', '{3402}', 10448, 2, 3, null, 'Ein randomisiertes US-Experiment zeigt: Training in fairem Verfahren senkt wahrgenommene Schikane und Gewalt. Dagegen: Inhalte hier meist unbestimmt, Effekte schwinden ohne Begleitung durch Vorgesetzte.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=226', 'https://cebcp.org/weisburd-procedural-justice-hot-spots/', 'belegt', '2026-10-21', false, true, 'blind', null),
  (10496, 34, 13, 'BE', 'Kurswechsel zu einer Deeskalationsstrategie bei Polizeieinsätzen auf der Straße.', '{3402}', 10449, 2, 3, null, 'Deeskalationsansätze senkten in einem US-Feldversuch Gewaltanwendung und Verletzungen deutlich. Dagegen: Belege stammen aus wenigen Programmen, Strategie ohne Training bleibt unbestimmt.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=229', 'https://nij.ojp.gov/topics/articles/what-works-de-escalation-training', 'belegt', '2026-10-21', false, true, 'blind', null),
  (10497, 34, 13, 'BE', 'Standardisierte Verfahren der Polizei im Umgang mit geschlechtsspezifischer und häuslicher Gewalt nach spanischem Vorbild.', '{3402}', null, 1, 3, null, 'Standardisierte Abläufe bei häuslicher Gewalt verbessern die Einsatzpraxis für Opfer, berühren Kontakte mit jungen Menschen aber nur am Rand.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=131', null, 'offen', '2026-10-21', false, true, 'blind', null),
  (10498, 34, 13, 'BE', 'Community Policing in die Fläche bringen: mehr Kontaktbereichsbeamt*innen, Fahrradstreifen und Präsenz an Hotspots.', '{3402}', 10451, 2, 2, null, 'Eine Meta-Analyse findet positive Effekte bürgernaher Polizeiarbeit auf Zufriedenheit und Legitimität, kaum auf Kriminalität. Dagegen: Gesamtbefund uneindeutig, braucht zusätzliches Personal.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=225', 'https://cris.huji.ac.il/en/publications/community-oriented-policing-to-reduce-crime-disorder-and-fear-and/', 'belegt', '2026-10-21', false, true, 'blind', null),
  (10499, 34, 13, 'BE', 'Empfehlungen der Berliner Polizeistudie umsetzen und Supervision, Einsatznachbereitung und Resilienzstärkung für Einsatzkräfte ausbauen.', '{3402}', 10452, 1, 3, null, 'Reflexion von Einsätzen kann Einsatzpraxis verbessern; ein Effekt auf den Umgang mit Betroffenen ist kaum untersucht.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=226', null, 'offen', '2026-10-21', false, true, 'blind', null),
  (10500, 34, 13, 'BE', 'Unabhängigen Polizeibeauftragten verbessern: mehr Kontrolle und Prüfung aller an ihn herangetragenen Sachverhalte.', '{3403}', 10457, 2, 3, null, 'Studien finden bei unabhängigen Stellen mit Befugnissen häufiger bestätigte Vorwürfe; die Designs sind aber schwach, andere Befunde gegenläufig.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=227', 'https://policing.counciloncj.org/assessing-the-evidence/xi-civilian-oversight', 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10501, 34, 13, 'BE', 'Bodycam-Einsatz auf die Polizei beschränken und nur auf Verlangen oder bei unmittelbarem Zwang anschalten.', '{3403}', 10454, 2, 3, null, 'Bodycams senken laut Campbell-Review Beschwerden, Effekt auf Gewalt unklar; feste Einschaltregeln scheinen zu helfen. Aufnahmen erleichtern die Klärung von Vorwürfen.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=228', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC8356344/', 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10502, 34, 13, 'MV', 'Reform der Aus- und Fortbildung der Polizei mit mehr politischer Bildung und besserer Vorbereitung auf Einsatzsituationen mit psychisch belasteten Menschen', '{3402}', 10448, 2, 3, null, 'Ein randomisiertes US-Experiment zeigt: Training in fairem Verfahren senkt wahrgenommene Schikane und Gewalt. Dagegen: Inhalte hier meist unbestimmt, Effekte schwinden ohne Begleitung durch Vorgesetzte.', 'https://gruene-mv.de/?wpdmdl=33772#page=77', 'https://cebcp.org/weisburd-procedural-justice-hot-spots/', 'belegt', '2026-10-21', false, true, 'blind', null),
  (10503, 34, 13, 'MV', 'Unterstützung der Polizeikräfte bei mentaler Belastung', '{3402}', 10452, 1, 3, null, 'Reflexion von Einsätzen kann Einsatzpraxis verbessern; ein Effekt auf den Umgang mit Betroffenen ist kaum untersucht.', 'https://gruene-mv.de/?wpdmdl=33772#page=77', null, 'offen', '2026-10-21', false, true, 'blind', null),
  (10504, 34, 13, 'MV', 'Bürgernahe Polizei mit mehr Präsenz vor Ort, etwa zu Fuß in den Quartieren und im Dialog mit Anwohnenden', '{3402}', 10451, 2, 2, null, 'Eine Meta-Analyse findet positive Effekte bürgernaher Polizeiarbeit auf Zufriedenheit und Legitimität, kaum auf Kriminalität. Dagegen: Gesamtbefund uneindeutig, braucht zusätzliches Personal.', 'https://gruene-mv.de/?wpdmdl=33772#page=76', 'https://cris.huji.ac.il/en/publications/community-oriented-policing-to-reduce-crime-disorder-and-fear-and/', 'belegt', '2026-10-21', false, true, 'blind', null),
  (10505, 34, 13, 'MV', 'Einrichtung eines unabhängigen Polizeibeauftragten für Hinweise und Beschwerden von Bürgerinnen, Bürgern und Polizeikräften', '{3403}', 10458, 1, 3, null, 'Eine Anlaufstelle erleichtert Beschwerden; Befunde deuten aber darauf hin, dass Stellen ohne echte Befugnisse wenig an der Aufklärung ändern.', 'https://gruene-mv.de/?wpdmdl=33772#page=77', 'https://policing.counciloncj.org/assessing-the-evidence/xi-civilian-oversight', 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10506, 34, 13, 'MV', 'Ausweitung der Kennzeichnungspflicht für Polizeikräfte auf alle Einsatzlagen', '{3403}', 10455, 2, 3, null, 'Kennzeichnung erleichtert die Identifizierung bei Vorwürfen, gerichtlich gebilligt. Dagegen: Wirkung auf Einstellungsquoten kaum untersucht, Identifizierung scheitert nur in einem Teil der Fälle.', 'https://gruene-mv.de/?wpdmdl=33772#page=78', null, 'offen', '2026-10-21', false, true, 'blind', null),
  (10507, 34, 13, 'MV', 'Verpflichtender Bodycam-Einsatz bei Androhung und Anwendung körperlicher Gewalt durch die Polizei', '{3403}', 10454, 2, 3, null, 'Bodycams senken laut Campbell-Review Beschwerden, Effekt auf Gewalt unklar; feste Einschaltregeln scheinen zu helfen. Aufnahmen erleichtern die Klärung von Vorwürfen.', 'https://gruene-mv.de/?wpdmdl=33772#page=77', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC8356344/', 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10508, 34, 13, 'ST', 'Aus- und Fortbildung der Polizei auf Antidiskriminierung, interkulturelle Kompetenz und Deeskalation ausrichten', '{3402}', 10448, 2, 3, null, 'Ein randomisiertes US-Experiment zeigt: Training in fairem Verfahren senkt wahrgenommene Schikane und Gewalt. Dagegen: Inhalte hier meist unbestimmt, Effekte schwinden ohne Begleitung durch Vorgesetzte.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=43', 'https://cebcp.org/weisburd-procedural-justice-hot-spots/', 'belegt', '2026-10-21', false, true, 'blind', null),
  (10509, 34, 13, 'ST', 'Polizei diverser aufstellen, gezielt Menschen mit Migrationsgeschichte, Frauen, queere Menschen und mehrsprachige Bewerber*innen ansprechen', '{3402}', 10453, 1, 3, null, 'Vielfältigeres Personal kann Kommunikation erleichtern; ob es das Verhalten bei Kontakten spürbar ändert, ist wenig belegt.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=43', null, 'offen', '2026-10-21', false, true, 'blind', null),
  (10510, 34, 13, 'ST', 'Unabhängige Polizeibeauftragte Stelle für Beschwerden und Fehlverhalten in der Polizei schaffen', '{3403}', 10457, 2, 3, null, 'Studien finden bei unabhängigen Stellen mit Befugnissen häufiger bestätigte Vorwürfe; die Designs sind aber schwach, andere Befunde gegenläufig.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=43', 'https://policing.counciloncj.org/assessing-the-evidence/xi-civilian-oversight', 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10511, 34, 13, 'ST', 'Beschwerden bei der Polizei nachvollziehbar dokumentieren und auswerten', '{3403}', null, 1, 3, null, 'Systematische Dokumentation und Auswertung von Beschwerden verbessert die Nachvollziehbarkeit, ändert aber nichts an der Unabhängigkeit der Prüfung.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=43', null, 'offen', '2026-10-21', false, true, 'blind', null),
  (10512, 34, 14, 'BE', 'Kontaktbereichsbeamte intensiver einsetzen und von zusätzlichen Tätigkeiten entlasten, um den Austausch zwischen Polizei und Bevölkerung zu verbessern', '{3402}', 10451, 2, 2, null, 'Eine Meta-Analyse findet positive Effekte bürgernaher Polizeiarbeit auf Zufriedenheit und Legitimität, kaum auf Kriminalität. Dagegen: Gesamtbefund uneindeutig, braucht zusätzliches Personal.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=67', 'https://cris.huji.ac.il/en/publications/community-oriented-policing-to-reduce-crime-disorder-and-fear-and/', 'belegt', '2026-10-21', false, true, 'blind', null),
  (10513, 34, 14, 'BE', 'Kriterien für kriminalitätsbelastete Orte präzisieren, öffentlich nachvollziehbar machen, regelmäßig evaluieren und bei Wegfall aufheben', '{3401}', 10446, 1, 3, null, 'Klarere Kriterien und Überprüfung können anlasslose Kontrollen begrenzen und nachvollziehbarer machen; ob die Zahl der Kontrollen spürbar sinkt, bleibt offen.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=67', null, 'offen', '2026-10-21', false, true, 'blind', null),
  (10514, 34, 14, 'BE', 'Verdachtsunabhängige Identitätsfeststellung und Durchsuchung an kriminalitätsbelasteten Orten als Sonderbefugnis der Polizei', '{3401}', 10443, 0, 3, null, 'Mehr Kontrollen und Befugnisse erhöhen die Zahl der Kontakte, die als belastend gelten; Studien finden nur schwache, uneinheitliche Effekte auf Kriminalität. Für das Ziel respektvoller, seltener Kontrollen spricht nichts.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=67', 'https://fullfact.org/crime/does-stop-search-work/', 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10515, 34, 14, 'BE', 'Umfangreiche Schulungen von Polizei, Staatsanwaltschaft und Gerichten zur Sensibilisierung gegen antisemitische Aussagen und Straftaten', '{3402}', 10450, 1, 3, null, 'Mehr oder modernere Ausbildung kann das Verhalten bei Kontakten verbessern, die Maßnahmen nennen aber keine Inhalte zu Kommunikation oder Umgang mit Betroffenen.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=78', null, 'offen', '2026-10-21', false, true, 'blind', null),
  (10516, 34, 14, 'MV', 'Aus- und Fortbildung der Polizei auf höchstem Niveau sichern; Ausbildungsstandort Güstrow personell und finanziell stärken', '{3402}', 10450, 1, 3, null, 'Mehr oder modernere Ausbildung kann das Verhalten bei Kontakten verbessern, die Maßnahmen nennen aber keine Inhalte zu Kommunikation oder Umgang mit Betroffenen.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=133', null, 'offen', '2026-10-21', false, true, 'blind', null),
  (10517, 34, 14, 'MV', 'Polizeibeauftragten als unabhängige Anlaufstelle für Bürger bei Beschwerden stärken', '{3403}', 10458, 1, 3, null, 'Eine Anlaufstelle erleichtert Beschwerden; Befunde deuten aber darauf hin, dass Stellen ohne echte Befugnisse wenig an der Aufklärung ändern.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=133', 'https://policing.counciloncj.org/assessing-the-evidence/xi-civilian-oversight', 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10518, 34, 14, 'MV', 'Pseudonymisierte Kennzeichnungspflicht für Polizeibeamte bei Einsätzen einführen', '{3403}', 10455, 2, 3, null, 'Kennzeichnung erleichtert die Identifizierung bei Vorwürfen, gerichtlich gebilligt. Dagegen: Wirkung auf Einstellungsquoten kaum untersucht, Identifizierung scheitert nur in einem Teil der Fälle.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=133', null, 'offen', '2026-10-21', false, true, 'blind', null),
  (10519, 34, 14, 'MV', 'Bürokratische Dokumentations- und Verwaltungspflichten der Polizei spürbar reduzieren', '{3403}', 10461, 0, 3, null, 'Weniger Dokumentation entlastet die Polizei, erschwert aber die Nachprüfung von Einsätzen und die Klärung von Vorwürfen.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=132', null, 'offen', '2026-10-21', false, true, 'blind', null),
  (10520, 34, 14, 'ST', 'Waffenverbotszonen im Land abschaffen, damit in diesen Zonen keine anlasslosen Personenkontrollen mehr möglich sind.', '{3401}', 10445, 2, 3, null, 'Weniger anlasslose Kontrollen senken die Zahl belastender Kontakte; ihr Nutzen gegen Kriminalität gilt als schwach. Dagegen: Wirkung der Abschaffung in Deutschland kaum untersucht, Polizei verliert ein Werkzeug.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=48', 'https://fullfact.org/crime/does-stop-search-work/', 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10521, 34, 14, 'ST', 'Konsequente und nachhaltige Fortbildung der Polizei zur Antidiskriminierung.', '{3402}', 10448, 2, 3, null, 'Ein randomisiertes US-Experiment zeigt: Training in fairem Verfahren senkt wahrgenommene Schikane und Gewalt. Dagegen: Inhalte hier meist unbestimmt, Effekte schwinden ohne Begleitung durch Vorgesetzte.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=37', 'https://cebcp.org/weisburd-procedural-justice-hot-spots/', 'belegt', '2026-10-21', false, true, 'blind', null),
  (10522, 34, 14, 'ST', 'Feste Ansprechpersonen für Antidiskriminierung in der Polizei aufbauen.', '{3403}', null, 1, 3, null, 'Interne Ansprechpersonen senken die Schwelle für Hinweise, sind aber nicht unabhängig und ohne Aufklärungsbefugnisse.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=37', null, 'offen', '2026-10-21', false, true, 'blind', null),
  (10523, 34, 15, null, 'Polizeibeauftragte und innerbehördliche Denunzierungsstellen abschaffen, Beweislastumkehr beenden', '{3403}', 10460, 0, 3, null, 'Entfernt eine unabhängige Beschwerdemöglichkeit beim Bund; Vorwürfe blieben allein bei Staatsanwaltschaften, deren häufige Einstellungen die Ursache sind.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=119', 'https://policing.counciloncj.org/assessing-the-evidence/xi-civilian-oversight', 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10524, 34, 15, null, 'Kontrollstellen und Razzien in sogenannten No-go-Areas durchführen', '{3401}', 10444, 0, 3, null, 'Erweiterte Befugnisse und mehr Kontrollen erhöhen die Zahl der Kontakte; für eine respektvollere oder nachvollziehbarere Behandlung bei Kontrollen bietet das keinen Ansatz.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=123', 'https://fullfact.org/crime/does-stop-search-work/', 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10525, 34, 15, null, 'Befugnisse der Bundespolizei erweitern, auch als Grenzbehörde außerhalb der Grenzübergangsstellen', '{3401}', 10444, 0, 3, null, 'Erweiterte Befugnisse und mehr Kontrollen erhöhen die Zahl der Kontakte; für eine respektvollere oder nachvollziehbarere Behandlung bei Kontrollen bietet das keinen Ansatz.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=126', 'https://fullfact.org/crime/does-stop-search-work/', 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10526, 34, 15, 'BE', 'Mehr Polizeikontrollen ohne konkreten Anlass in Problemvierteln', '{3401}', 10443, 0, 3, null, 'Mehr Kontrollen und Befugnisse erhöhen die Zahl der Kontakte, die als belastend gelten; Studien finden nur schwache, uneinheitliche Effekte auf Kriminalität. Für das Ziel respektvoller, seltener Kontrollen spricht nichts.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=13', 'https://fullfact.org/crime/does-stop-search-work/', 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10527, 34, 15, 'BE', 'Rechtliche Grundlage für nächtliche Ausgangssperren für jugendliche Intensivtäter', '{3401}', 10443, 0, 3, null, 'Mehr Kontrollen und Befugnisse erhöhen die Zahl der Kontakte, die als belastend gelten; Studien finden nur schwache, uneinheitliche Effekte auf Kriminalität. Für das Ziel respektvoller, seltener Kontrollen spricht nichts.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=13', 'https://fullfact.org/crime/does-stop-search-work/', 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10528, 34, 15, 'BE', 'Bezirkspolizei bei den Ordnungsämtern mit Identitätsfeststellung, Durchsuchung, Platzverweisen und unmittelbarem Zwang', '{3401}', 10443, 0, 3, null, 'Mehr Kontrollen und Befugnisse erhöhen die Zahl der Kontakte, die als belastend gelten; Studien finden nur schwache, uneinheitliche Effekte auf Kriminalität. Für das Ziel respektvoller, seltener Kontrollen spricht nichts.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=12', 'https://fullfact.org/crime/does-stop-search-work/', 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10529, 34, 15, 'BE', 'Sicherstellung einer ausreichenden Ausbildung des Polizei-Nachwuchses', '{3402}', 10450, 1, 3, null, 'Mehr oder modernere Ausbildung kann das Verhalten bei Kontakten verbessern, die Maßnahmen nennen aber keine Inhalte zu Kommunikation oder Umgang mit Betroffenen.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=13', null, 'offen', '2026-10-21', false, true, 'blind', null),
  (10530, 34, 15, 'MV', 'Dokumentationspflichten bei Polizeieinsätzen im SOG zurücknehmen', '{3403}', 10461, 0, 3, null, 'Weniger Dokumentation entlastet die Polizei, erschwert aber die Nachprüfung von Einsätzen und die Klärung von Vorwürfen.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=38', null, 'offen', '2026-10-21', false, true, 'blind', null),
  (10531, 34, 15, 'MV', 'Disziplinarverfahren gegen Polizeibeamte durch verbesserte Prozesse und mehr Personal straffen', '{3403}', 10462, 1, 3, null, 'Schnellere, konsequente Disziplinarverfahren können Fehlverhalten ahnden; sie bleiben aber polizeiintern, die Wirkung auf die Klärung von Vorwürfen ist kaum untersucht.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=38', null, 'offen', '2026-10-21', false, true, 'blind', null),
  (10532, 34, 15, 'MV', 'Fortlaufende Auffrischungs- und Vertiefungstrainings für die Polizei, mit Zeit und Infrastruktur', '{3402}', 10450, 1, 3, null, 'Mehr oder modernere Ausbildung kann das Verhalten bei Kontakten verbessern, die Maßnahmen nennen aber keine Inhalte zu Kommunikation oder Umgang mit Betroffenen.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=38', null, 'offen', '2026-10-21', false, true, 'blind', null),
  (10533, 34, 15, 'ST', 'Funktion des Polizeibeauftragten abschaffen.', '{3403}', 10459, 0, 3, null, 'Entfernt eine unabhängige Beschwerdemöglichkeit; zur Klärung von Fehlern bleiben nur die Wege, deren hohe Einstellungsquote die Ursache ist.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=109', 'https://policing.counciloncj.org/assessing-the-evidence/xi-civilian-oversight', 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10534, 34, 15, 'ST', 'Interne Ermittlungen nach Schusswaffengebrauch nur noch bei konkretem Verdacht auf Fehlverhalten einleiten.', '{3403}', null, 0, 3, null, 'Weniger interne Ermittlungen nach Schusswaffengebrauch erschweren die Klärung möglicher Fehler.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=106', null, 'offen', '2026-10-21', false, true, 'blind', null),
  (10535, 34, 15, 'ST', 'Aussetzung der Förderung bei Disziplinarverfahren erst mit staatsanwaltlichen Ermittlungen wirksam werden lassen.', '{3403}', null, 0, 3, null, 'Beschränkt Folgen laufender Disziplinarverfahren für Beamte; für die Klärung von Vorwürfen Betroffener bringt das nichts.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=108', null, 'offen', '2026-10-21', false, true, 'blind', null),
  (10536, 34, 16, null, 'Anlasslose polizeiliche Kontrollbefugnisse abschaffen; rassistische Polizeikontrollen gesetzlich verbieten.', '{3401}', null, 2, 3, null, 'Abschaffung anlassloser Kontrollbefugnisse senkt belastende Kontakte mit der Bundespolizei; ihr Nutzen gegen Kriminalität gilt als schwach. Dagegen: deutsche Wirkung kaum untersucht.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=53', 'https://fullfact.org/crime/does-stop-search-work/', 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10537, 34, 16, null, 'Polizei soll ansprechbar sein und deeskalierend auftreten.', '{3402}', null, 1, 3, null, 'Ansprechbares, deeskalierendes Auftreten setzt an der Einsatzpraxis an, bleibt aber ohne konkretes Instrument und betrifft beim Bund nur die Bundespolizei.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=48', null, 'offen', '2026-10-21', false, true, 'blind', null),
  (10538, 34, 16, null, 'Einsatz von Pfefferspray durch die Polizei stark einschränken und bei Versammlungen und Veranstaltungen verbieten.', '{3402}', null, 1, 2, null, 'Einschränkung von Pfefferspray kann Verletzungen bei Ansammlungen mindern; Bund regelt nur Bundespolizei, Versammlungsrecht und Landespolizei liegen bei den Ländern.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=49', null, 'offen', '2026-10-21', false, true, 'blind', null),
  (10539, 34, 16, null, 'Psychologische Unterstützung für Polizeibeamt*innen verbessern.', '{3402}', null, 1, 3, null, 'Psychologische Unterstützung kann Belastung und damit Fehlreaktionen mindern; ein Effekt auf den Umgang mit Betroffenen ist kaum untersucht.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=49', null, 'offen', '2026-10-21', false, true, 'blind', null),
  (10540, 34, 16, null, 'Individuelle Kennzeichnungspflicht für Polizeibeamt*innen einführen.', '{3403}', 10456, 2, 3, null, 'Kennzeichnung erleichtert die Identifizierung bei Vorwürfen gegen Bundespolizisten. Dagegen: Wirkung auf die Aufklärung kaum untersucht.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=49', null, 'offen', '2026-10-21', false, true, 'blind', null),
  (10541, 34, 16, null, 'Einsatzprotokolle und Polizeivideos bei Treuhandstellen aufbewahren, um Übergriffe aufzuklären und zu verhindern.', '{3403}', null, 1, 2, null, 'Unabhängig verwahrte Protokolle und Videos sichern Beweise für die Klärung von Vorwürfen; Konzept und Wirkung unerprobt, für Landespolizeien nur über Länder.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=49', null, 'offen', '2026-10-21', false, true, 'blind', null),
  (10542, 34, 16, 'BE', 'Verdachtsunabhängige Polizeikontrollen abschaffen', '{3401}', 10445, 2, 3, null, 'Weniger anlasslose Kontrollen senken die Zahl belastender Kontakte; ihr Nutzen gegen Kriminalität gilt als schwach. Dagegen: Wirkung der Abschaffung in Deutschland kaum untersucht, Polizei verliert ein Werkzeug.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=177', 'https://fullfact.org/crime/does-stop-search-work/', 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10543, 34, 16, 'BE', 'Polizei muss bei Identitätsfeststellung und Durchsuchung schriftlich Grund und Rechtsgrundlage nennen', '{3401}', 10447, 2, 3, null, 'Erfahrungen aus Spanien (Fuenlabrada) zeigen mehr Transparenz, weniger Spannung und selektivere Kontrollen. Dagegen: kaum kontrollierte Studien, zusätzlicher Aufwand für die Polizei.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=290', 'https://www.justiceinitiative.org/voices/q-and-a-how-a-system-to-document-police-stops-improved-policing-in-fuenlabrada-spain', 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10544, 34, 16, 'BE', 'Fortbildung der Polizei im Umgang mit Menschen in psychischen Ausnahmesituationen', '{3402}', 10448, 2, 3, null, 'Ein randomisiertes US-Experiment zeigt: Training in fairem Verfahren senkt wahrgenommene Schikane und Gewalt. Dagegen: Inhalte hier meist unbestimmt, Effekte schwinden ohne Begleitung durch Vorgesetzte.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=291', 'https://cebcp.org/weisburd-procedural-justice-hot-spots/', 'belegt', '2026-10-21', false, true, 'blind', null),
  (10545, 34, 16, 'BE', 'Nicht-polizeiliche multiprofessionelle Krisenteams aufbauen, die nicht zur Polizei gehören', '{3402}', null, 1, 2, null, 'Nichtpolizeiliche Krisenteams ersetzen Polizeikontakte in psychischen Krisen; betrifft junge Menschen nur am Rand, Aufbau braucht Personal und Jahre.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=291', null, 'offen', '2026-10-21', false, true, 'blind', null),
  (10546, 34, 16, 'BE', 'Deeskalationskonzepte bei Versammlungen konsequent umsetzen', '{3402}', 10449, 2, 3, null, 'Deeskalationsansätze senkten in einem US-Feldversuch Gewaltanwendung und Verletzungen deutlich. Dagegen: Belege stammen aus wenigen Programmen, Strategie ohne Training bleibt unbestimmt.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=293', 'https://nij.ojp.gov/topics/articles/what-works-de-escalation-training', 'belegt', '2026-10-21', false, true, 'blind', null),
  (10547, 34, 16, 'BE', 'Einsatz von Tasern außerhalb von Spezialkräften ablehnen', '{3402}', null, 1, 3, null, 'Verzicht auf Taser im Streifendienst vermeidet ein riskantes Zwangsmittel; Wirkung auf den Umgang bei Kontakten insgesamt kaum untersucht.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=291', null, 'offen', '2026-10-21', false, true, 'blind', null),
  (10548, 34, 16, 'BE', 'Unabhängigen Polizeibeauftragten mit Befugnissen und Personal ausbauen', '{3403}', 10457, 2, 3, null, 'Studien finden bei unabhängigen Stellen mit Befugnissen häufiger bestätigte Vorwürfe; die Designs sind aber schwach, andere Befunde gegenläufig.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=290', 'https://policing.counciloncj.org/assessing-the-evidence/xi-civilian-oversight', 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10549, 34, 16, 'BE', 'Bodycam-Aufzeichnungen: Einsicht für Bürger*innen und automatische Aktivierung beim Waffeneinsatz', '{3403}', 10454, 2, 3, null, 'Bodycams senken laut Campbell-Review Beschwerden, Effekt auf Gewalt unklar; feste Einschaltregeln scheinen zu helfen. Aufnahmen erleichtern die Klärung von Vorwürfen.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=290', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC8356344/', 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10550, 34, 16, 'BE', 'Zivilgesellschaftliche Initiativen unterstützen, die polizeiliches Handeln beobachten', '{3403}', null, 1, 3, null, 'Zivilgesellschaftliche Beobachtung macht Fehlverhalten sichtbar und berät Betroffene, hat aber keine Befugnisse zur Aufklärung.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=290', null, 'offen', '2026-10-21', false, true, 'blind', null),
  (10551, 34, 16, 'BE', 'Schutz für Beschäftigte, die Fehlverhalten melden, durch Umsetzung des Hinweisgeberschutzgesetzes', '{3403}', null, 1, 3, null, 'Schutz für Hinweisgebende in der Polizei kann Fehlverhalten sichtbar machen; Wirkung auf die Aufklärung von Vorwürfen kaum untersucht.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=297', null, 'offen', '2026-10-21', false, true, 'blind', null),
  (10552, 34, 16, 'MV', 'Unabhängige Beschwerdestelle mit Mandat, Ressourcen und Befugnissen, um Fehlverhalten der Polizei zu verfolgen', '{3403}', 10457, 2, 3, null, 'Studien finden bei unabhängigen Stellen mit Befugnissen häufiger bestätigte Vorwürfe; die Designs sind aber schwach, andere Befunde gegenläufig.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=20', 'https://policing.counciloncj.org/assessing-the-evidence/xi-civilian-oversight', 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10553, 34, 16, 'MV', 'Kontrollquittungen für Betroffene polizeilicher Maßnahmen einführen', '{3401}', 10447, 2, 3, null, 'Erfahrungen aus Spanien (Fuenlabrada) zeigen mehr Transparenz, weniger Spannung und selektivere Kontrollen. Dagegen: kaum kontrollierte Studien, zusätzlicher Aufwand für die Polizei.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=20', 'https://www.justiceinitiative.org/voices/q-and-a-how-a-system-to-document-police-stops-improved-policing-in-fuenlabrada-spain', 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10554, 34, 16, 'MV', 'Demokratie- und Grundrechtsbildung sowie Fehlerkultur in Aus- und Fortbildung der Polizei stärken', '{3402}', 10448, 2, 3, null, 'Ein randomisiertes US-Experiment zeigt: Training in fairem Verfahren senkt wahrgenommene Schikane und Gewalt. Dagegen: Inhalte hier meist unbestimmt, Effekte schwinden ohne Begleitung durch Vorgesetzte.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=20', 'https://cebcp.org/weisburd-procedural-justice-hot-spots/', 'belegt', '2026-10-21', false, true, 'blind', null),
  (10555, 34, 16, 'ST', 'Regelmäßige Fortbildungen der Polizei zu Menschenrechten und interkultureller Kompetenz.', '{3402}', 10448, 2, 3, null, 'Ein randomisiertes US-Experiment zeigt: Training in fairem Verfahren senkt wahrgenommene Schikane und Gewalt. Dagegen: Inhalte hier meist unbestimmt, Effekte schwinden ohne Begleitung durch Vorgesetzte.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=128', 'https://cebcp.org/weisburd-procedural-justice-hot-spots/', 'belegt', '2026-10-21', false, true, 'blind', null),
  (10556, 34, 16, 'ST', 'Bürgerforen zur Polizeiarbeit vor Ort, Anhörungen und Rechenschaftsberichte zu Sicherheitspolitik.', '{3402}', null, 1, 3, null, 'Bürgerforen und Rechenschaftsberichte fördern Austausch und Transparenz; die Wirkung auf das Verhalten bei einzelnen Kontakten ist gering.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=128', null, 'offen', '2026-10-21', false, true, 'blind', null),
  (10557, 34, 16, 'ST', 'Eine unabhängige Polizeibeschwerdestelle mit eigenen Ermittlungsbefugnissen einrichten.', '{3403}', 10457, 2, 3, null, 'Studien finden bei unabhängigen Stellen mit Befugnissen häufiger bestätigte Vorwürfe; die Designs sind aber schwach, andere Befunde gegenläufig.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=128', 'https://policing.counciloncj.org/assessing-the-evidence/xi-civilian-oversight', 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10558, 34, 16, 'ST', 'Individuelle Kennzeichnungspflicht für Polizeikräfte.', '{3403}', 10455, 2, 3, null, 'Kennzeichnung erleichtert die Identifizierung bei Vorwürfen, gerichtlich gebilligt. Dagegen: Wirkung auf Einstellungsquoten kaum untersucht, Identifizierung scheitert nur in einem Teil der Fälle.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=129', null, 'offen', '2026-10-21', false, true, 'blind', null),
  (10559, 34, 16, 'ST', 'Automatischer Einsatz von Bodycams bei Schusswaffengebrauch und Taser-Einsatz.', '{3403}', 10454, 2, 3, null, 'Bodycams senken laut Campbell-Review Beschwerden, Effekt auf Gewalt unklar; feste Einschaltregeln scheinen zu helfen. Aufnahmen erleichtern die Klärung von Vorwürfen.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=129', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC8356344/', 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10560, 34, 17, null, 'Aus- und Fortbildung der Polizei in Akademien und Trainingszentren ausbauen', '{3402}', null, 1, 3, null, 'Bessere Ausbildung in Akademien kann das Einsatzverhalten verbessern; Inhalte zu Kommunikation und Umgang mit Betroffenen werden nicht genannt.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=35', null, 'offen', '2026-10-21', false, true, 'blind', null),
  (10561, 34, 17, 'BE', 'Einsatzkräfte sollen stärker in Deeskalation geschult werden; bestehende Deeskalationsstrategien sind anzuwenden und auszuwerten.', '{3402}', 10448, 2, 3, null, 'Ein randomisiertes US-Experiment zeigt: Training in fairem Verfahren senkt wahrgenommene Schikane und Gewalt. Dagegen: Inhalte hier meist unbestimmt, Effekte schwinden ohne Begleitung durch Vorgesetzte.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=39', 'https://cebcp.org/weisburd-procedural-justice-hot-spots/', 'belegt', '2026-10-21', false, true, 'blind', null),
  (10562, 34, 17, 'BE', 'Zusätzliche gemeinsame Kontrollen von Ordnungsamt, Polizei und Zoll, auch in Innenräumen wie der Schankwirtschaft.', '{3401}', 10443, 0, 3, null, 'Mehr Kontrollen und Befugnisse erhöhen die Zahl der Kontakte, die als belastend gelten; Studien finden nur schwache, uneinheitliche Effekte auf Kriminalität. Für das Ziel respektvoller, seltener Kontrollen spricht nichts.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=41', 'https://fullfact.org/crime/does-stop-search-work/', 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10563, 34, 17, 'BE', 'Bei Drogenkonsum im Umfeld von Schulen und Kitas sollen neben Platzverweisen Sicherheitszonen eingerichtet werden.', '{3401}', 10443, 0, 3, null, 'Mehr Kontrollen und Befugnisse erhöhen die Zahl der Kontakte, die als belastend gelten; Studien finden nur schwache, uneinheitliche Effekte auf Kriminalität. Für das Ziel respektvoller, seltener Kontrollen spricht nichts.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=41', 'https://fullfact.org/crime/does-stop-search-work/', 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10564, 34, 17, 'BE', 'Bei unverhältnismäßiger Gewalt durch Polizeikräfte sofortige und konsequente Disziplinarmaßnahmen sowie Überprüfung der Einsatzkräfte.', '{3403}', 10462, 1, 3, null, 'Schnellere, konsequente Disziplinarverfahren können Fehlverhalten ahnden; sie bleiben aber polizeiintern, die Wirkung auf die Klärung von Vorwürfen ist kaum untersucht.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=39', null, 'offen', '2026-10-21', false, true, 'blind', null),
  (10565, 34, 17, 'MV', 'Fortbildung der Polizei mit praxisnahen Standards für Einsatznachbereitung und Fehlerkultur.', '{3402}', 10448, 2, 3, null, 'Ein randomisiertes US-Experiment zeigt: Training in fairem Verfahren senkt wahrgenommene Schikane und Gewalt. Dagegen: Inhalte hier meist unbestimmt, Effekte schwinden ohne Begleitung durch Vorgesetzte.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=68', 'https://cebcp.org/weisburd-procedural-justice-hot-spots/', 'belegt', '2026-10-21', false, true, 'blind', null);

